import data from "./git-stats.json";

// Generated by `npm run git-stats` from the project repos next to this one.
export type GitStats = {
  commits: number;
  claudeCommits: number;
  firstCommit: string;
  firstClaudeCommit: string | null;
  lastCommit: string;
  activeDays: number;
  lastSubject: string;
  lastHash: string;
  branch: string;
  codeLines: number;
  testFiles: number;
};

export const gitStatsDate: string = data.generatedAt;

const byFolder = data.projects as Record<string, GitStats>;

export function gitStatsFor(folder: string): GitStats | undefined {
  return byFolder[folder];
}

export function gitTotals() {
  const all = Object.values(byFolder);
  const sum = (k: "commits" | "claudeCommits" | "codeLines") =>
    all.reduce((n, s) => n + s[k], 0);
  return {
    commits: sum("commits"),
    claudeCommits: sum("claudeCommits"),
    codeLines: sum("codeLines"),
  };
}

const dateFmt = new Intl.DateTimeFormat("en-GB", {
  day: "numeric",
  month: "short",
  year: "numeric",
  timeZone: "UTC",
});

export function formatDate(iso: string) {
  return dateFmt.format(new Date(`${iso}T00:00:00Z`));
}

export function formatLines(n: number) {
  return n >= 1000 ? `${(n / 1000).toFixed(1)}k` : String(n);
}
